public class InPlaceMatrixRotatorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static int[][] grid(int n) {
        int[][] m = new int[n][n];
        int v = 1;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                m[r][c] = v++;
            }
        }
        return m;
    }

    static String show(int[][] m) {
        return java.util.Arrays.deepToString(m);
    }

    public static void main(String[] args) {
        int[][] three = grid(3);
        int[][] rotated = InPlaceMatrixRotator.rotateClockwise(three);
        check("rotateClockwise(3x3)", "[[7, 4, 1], [8, 5, 2], [9, 6, 3]]", show(rotated));
        check("rotateClockwise returns the same array object", true, rotated == three);
        check("row objects are reused", true, rotated != null && rotated[0] == three[0]);

        int[][] four = grid(4);
        InPlaceMatrixRotator.rotateClockwise(four);
        check("rotateClockwise(4x4)",
                "[[13, 9, 5, 1], [14, 10, 6, 2], [15, 11, 7, 3], [16, 12, 8, 4]]", show(four));

        int[][] twice = grid(3);
        InPlaceMatrixRotator.rotateTimes(twice, 2);
        check("rotateTimes(3x3, 2)", "[[9, 8, 7], [6, 5, 4], [3, 2, 1]]", show(twice));

        int[][] back = grid(3);
        InPlaceMatrixRotator.rotateTimes(back, -1);
        check("rotateTimes(3x3, -1) is counter-clockwise", "[[3, 6, 9], [2, 5, 8], [1, 4, 7]]", show(back));

        int[][] full = grid(3);
        InPlaceMatrixRotator.rotateTimes(full, 8);
        check("rotateTimes(3x3, 8) is a no-op", "[[1, 2, 3], [4, 5, 6], [7, 8, 9]]", show(full));

        int[][] huge = grid(2);
        InPlaceMatrixRotator.rotateTimes(huge, 1000000001);
        check("rotateTimes(2x2, 1000000001)", "[[3, 1], [4, 2]]", show(huge));

        int[][] one = {{42}};
        check("1x1 unchanged", "[[42]]", show(InPlaceMatrixRotator.rotateClockwise(one)));
        int[][] empty = new int[0][0];
        check("0x0 returns the same object", true, InPlaceMatrixRotator.rotateClockwise(empty) == empty);
        check("null stays null", null, InPlaceMatrixRotator.rotateTimes(null, 3));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

