public class InPlaceMatrixRotator {

    public static int[][] rotateClockwise(int[][] matrix) {
        if (matrix == null || matrix.length < 2) {
            return matrix;
        }
        int n = matrix.length;
        for (int r = 0; r < n; r++) {
            for (int c = r + 1; c < n; c++) {
                int temp = matrix[r][c];
                matrix[r][c] = matrix[c][r];
                matrix[c][r] = temp;
            }
        }
        for (int r = 0; r < n; r++) {
            int left = 0;
            int right = n - 1;
            while (left < right) {
                int temp = matrix[r][left];
                matrix[r][left] = matrix[r][right];
                matrix[r][right] = temp;
                left++;
                right--;
            }
        }
        return matrix;
    }

    public static int[][] rotateTimes(int[][] matrix, int quarterTurns) {
        if (matrix == null) {
            return null;
        }
        int turns = ((quarterTurns % 4) + 4) % 4;
        for (int i = 0; i < turns; i++) {
            rotateClockwise(matrix);
        }
        return matrix;
    }
}
